// Build engine/_upstream.generated.mjs from the verbatim upstream sources.
//
// Why generate instead of editing: the upstream files are browser globals
// (`Typeset.linebreak = ...`). Wrapping them at build time keeps `src/` and
// `lib/` byte-identical to bramstein/typeset, so `git log -- src/linebreak.js`
// still shows only upstream commits. The generated file records a sha256 per
// source file and `npm test` re-verifies them, so a silent hand-edit fails CI.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const FILES = [
  'src/linked-list.js',
  'lib/hypher.js',
  'lib/en-us.js',
  'src/linebreak.js',
  'src/formatter.js'
];
const OUT = path.join(ROOT, 'engine', '_upstream.generated.mjs');

const sha256 = (buf) => crypto.createHash('sha256').update(buf).digest('hex');

// Hash and embed the LF-normalised text, not the on-disk bytes. A Windows
// checkout has CRLF in the working tree while the repository stores LF; if the
// recorded hash followed the checkout, `npm test` would pass on the machine
// that generated it and fail on every fresh clone.
const normalise = (text) => text.replace(/\r\n/g, '\n');

const parts = [];
const hashes = {};
for (const rel of FILES) {
  const text = normalise(fs.readFileSync(path.join(ROOT, rel), 'utf8'));
  hashes[rel] = sha256(Buffer.from(text, 'utf8'));
  parts.push(`// ---- ${rel} ----\n${text}`);
}

const header = [
  '// AUTO-GENERATED by scripts/build-upstream.mjs — DO NOT EDIT.',
  '//',
  '// Sources are copied verbatim from bramstein/typeset (BSD-2-Clause).',
  '// Regenerate with: npm run build',
  '//',
  ...FILES.map((f) => `//   ${f}  sha256=${hashes[f]}`),
  ''
].join('\n');

const body = `\nconst Typeset = (function () {\n${parts.join('\n')}\nreturn Typeset;\n})();\n\nexport { Typeset };\nexport const SOURCE_SHA256 = ${JSON.stringify(hashes, null, 2)};\n`;

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, header + body, 'utf8');

const bytes = fs.statSync(OUT).size;
console.log(`wrote ${path.relative(ROOT, OUT)} (${bytes} bytes, ${FILES.length} sources)`);
for (const f of FILES) console.log(`  ${f} ${hashes[f].slice(0, 16)}`);
